def shortlist(candidates, predict, need):
    ranked = []
    for c in candidates:
        p, sigma = predict(c)          # property + uncertainty
        if p - sigma >= need:          # conservative: use lower bound
            ranked.append((c, p, sigma))
    return sorted(ranked, key=lambda r: -(r[1]-r[2]))

def event_sequence(p_initiate, safeguards):
    # probability that all safeguards fail after an initiating event
    p = p_initiate
    for s in safeguards:
        p *= (1 - s.reliability)
    return p

def reproduce(manifest, workdir):
    checkout(manifest['commit'])
    restore_env(manifest['env'])
    for step in manifest['steps']:
        run(step['cmd'], seed=step.get('seed'))
    return verify(workdir, manifest['expected'], manifest['tier'])

import math

def inventory(I0, half_life, days, produced_per_day, used_per_day):
    lam = math.log(2)/half_life
    I = I0
    for _ in range(days):
        I = I*math.exp(-lam) + produced_per_day - used_per_day
    return max(I, 0.0)

def frequency_response(f, f_nominal, droop, p_now, p_max):
    # simple droop control: adjust power toward restoring frequency
    dp = -(f - f_nominal)/f_nominal / droop
    return min(max(p_now + dp*p_max, 0), p_max)

def remaining_life(trend, current, threshold):
    # trend: degradation per unit time (with uncertainty upstream)
    if trend <= 0: return float('inf')
    return (threshold - current) / trend

def submission_index(analyses):
    return [{'claim': a['claim'],
            'status': a['status'],        # demonstrated | simulated | open
            'uncertainty': a['uncertainty'],
            'reproduce': a['manifest_id']} for a in analyses]

def optimize_with_surrogate(surrogate, real_sim, x0, refine_if):
    x = x0
    while True:
        x = surrogate.propose_next(x)
        mean, var = surrogate.predict(x)
        if refine_if(var):                 # uncertain? verify with real sim
            surrogate.add(x, real_sim(x))
        else:
            return x

def twin_step(twin, sensors):
    predicted = twin.advance()
    twin.correct(measurement=sensors, prediction=predicted)  # data assimilation
    return twin.state()

import numpy as np

def propagate(model, sampler, n=10000):
    outs = np.array([model(sampler()) for _ in range(n)])
    return {'mean': outs.mean(), 'p05': np.percentile(outs,5),
            'p95': np.percentile(outs,95)}

def run_dag(nodes, deps, execute):
    done = set()
    while len(done) < len(nodes):
        ready = [n for n in nodes if n not in done
                 and all(d in done for d in deps[n])]
        for n in ready:
            execute(n)          # logs version, inputs, result
            done.add(n)

def reconstruct(measurements, forward, prior, reg):
    # minimize misfit + regularization (schematic)
    def cost(state):
        return misfit(forward(state), measurements) + reg*prior(state)
    return minimize(cost)

def disruption_alarm(signals, model, physics_limits, threshold):
    if physics_limits.violated(signals):
        return True                        # hard limit: act regardless
    p = model.predict_proba(signals)
    return p > threshold                    # learned precursor

def summarize(doc, extract, condense):
    facts = extract(doc)                 # pull numbers verbatim with context
    prose = condense(doc.narrative)      # compress the discussion
    return {'summary': prose, 'facts': facts, 'source': doc.id}

def impact(graph, changed_node):
    affected, frontier = set(), [changed_node]
    while frontier:
        n = frontier.pop()
        for m in graph.dependents(n):
            if m not in affected:
                affected.add(m); frontier.append(m)
    return affected

def top_probability(cut_sets, p):
    # rare-event approximation: sum of cut-set probabilities
    total = 0.0
    for cs in cut_sets:
        prod = 1.0
        for basic in cs:
            prod *= p[basic]
        total += prod
    return total

def risk(scenarios):
    # scenario: frequency (per year) and consequence measure
    return sum(s['frequency'] * s['consequence'] for s in scenarios)

def end_of_life(dpa_rate, dpa_limit):
    if dpa_rate <= 0: return float('inf')
    return dpa_limit / dpa_rate   # years to reach damage limit

import math

def permeability(P0, activation_energy, T, R=8.314):
    # Arrhenius: permeability rises with temperature
    return P0 * math.exp(-activation_energy/(R*T))

def wall_temperature(q_flux, h, t_coolant):
    # simple 1D: wall temp rises above coolant by flux/coefficient
    return t_coolant + q_flux / h

def cycles_to_failure(stress_amp, A, m):
    # power-law stress-life form: higher stress, fewer cycles
    return A * (stress_amp ** -m)

def critical_path(tasks, durations, deps):
    finish = {}
    for t in topological_order(tasks, deps):
        start = max([finish[d] for d in deps[t]], default=0)
        finish[t] = start + durations[t]
    return max(finish.values())   # project length

def check_invariant(model, invariant):
    # exhaustively explore reachable states of a finite model
    seen, frontier = set(), [model.initial()]
    while frontier:
        s = frontier.pop()
        if not invariant(s):
            return ('violated', s)     # counterexample
        for s2 in model.successors(s):
            if s2 not in seen:
                seen.add(s2); frontier.append(s2)
    return ('holds', None)

def validate(record, checks):
    failures = [name for name, ok in checks.items() if not ok(record)]
    if failures:
        raise DataQualityError(record['id'], failures)  # stop the pipeline
    return record
